import { FC } from 'react';

interface TextareaProps {
    /** 输入值 (受控) */
    value?: string;
    /** 默认值 (非受控) */
    defaultValue?: string;
    /** 占位文本 */
    placeholder?: string;
    /** 是否禁用 */
    disabled?: boolean;
    /** 最大长度 */
    maxLength?: number;
    /** 是否显示字数统计 */
    showCount?: boolean;
    /** 是否自动增高 */
    autoHeight?: boolean;
    /** 行数 (固定高度时) */
    rows?: number;
    /** 值变化回调 */
    onChange?: (value: string) => void;
    /** 聚焦回调 */
    onFocus?: (e: any) => void;
    /** 失焦回调 */
    onBlur?: (e: any) => void;
    /** 自定义类名 */
    className?: string;
}

declare const Textarea: FC<TextareaProps>;

export { Textarea, Textarea as default };
export type { TextareaProps };
